import test from'node:test';import assert from'node:assert/strict';import{createPluginManager}from'../index.mjs';
test('native calls, reuse, nonowner and arbitrary sources denied; confirmation bound to request',async()=>{const agent={};let installs=0;const ctx={pluginManager:{listBundles:async()=>[{name:'@ace-zone/dsh-market'}],listPlugins:async()=>[{entryId:'p'}],inspect:async spec=>({spec}),installBundle:async()=>{installs++;return{ok:true}},setPluginEnabled:async()=>({ok:true})},pluginMarket:{listIndexes:async()=>[{url:'https://configured.invalid/index'}],search:async(url,query)=>({url,query})}};const x=createPluginManager({ctx,isOwner:()=>true,confirmChange:async r=>({requestId:r.requestId,approved:true})}).bind(agent,'owner');const exec={agent};await assert.rejects(x.invoke('list',{}, {agent:{}}),/OWNER_ONLY/);await assert.rejects(x.invoke('install',{spec:'https://evil.invalid/x'},exec),/REGISTRY_SPEC_REQUIRED/);assert.equal((await x.invoke('install',{spec:'@ace-zone/dsh-market'},exec)).status,'already_installed');await x.invoke('install',{spec:'new-package@1.0.0'},exec);assert.equal(installs,1);await assert.rejects(x.invoke('search',{indexUrl:'https://evil.invalid'},exec),/INDEX_NOT_CONFIGURED/);const deny=createPluginManager({ctx,isOwner:()=>true}).bind(agent,'owner');await assert.rejects(deny.invoke('enable',{entryId:'p'},exec),/CONFIRMATION_REQUIRED/);});
